// FV-Lang HTTP Server - Formal Test
// 정식 컴파일러로 테스트할 간단한 HTTP 서버

#[derive(Clone)]
struct HttpRequest {
    method: String,
    path: String,
    headers: String,
}

#[derive(Clone)]
struct HttpResponse {
    status: i32,
    body: String,
    content_type: String,
}

// HTTP 요청 파싱
fn parse_http_request(raw: String) -> HttpRequest {
    let lines = raw.as_str(); // 첫 줄 분석
    HttpRequest {
        method: "GET".to_string(),
        path: "/health".to_string(),
        headers: raw.clone(),
    }
}

// HTTP 응답 생성
fn create_response(status: i32, body: String) -> HttpResponse {
    HttpResponse {
        status: status,
        body: body,
        content_type: "application/json".to_string(),
    }
}

// 헬스 체크 응답
fn handle_health() -> HttpResponse {
    let body = "{\"status\":\"healthy\",\"version\":\"1.0.0\"}".to_string();
    create_response(200i32, body)
}

// 메트릭 응답
fn handle_metrics() -> HttpResponse {
    let body = "{\"requests\":42,\"uptime_seconds\":3600}".to_string();
    create_response(200i32, body)
}

// 라우팅 엔진
fn route_request(path: String) -> HttpResponse {
    if path == "/health" {
        handle_health()
    } else if path == "/metrics" {
        handle_metrics()
    } else {
        create_response(404i32, "{\"error\":\"not found\"}".to_string())
    }
}

// HTTP 서버 시뮬레이션
fn run_http_server() -> bool {
    println!("HTTP Server starting on port 8080...");

    // 테스트 요청 1: /health
    let req1 = HttpRequest {
        method: "GET".to_string(),
        path: "/health".to_string(),
        headers: "".to_string(),
    };
    let resp1 = route_request(req1.path);
    println!("Request: GET /health");
    println!("Response: {} - {}", resp1.status, resp1.body);

    // 테스트 요청 2: /metrics
    let req2 = HttpRequest {
        method: "GET".to_string(),
        path: "/metrics".to_string(),
        headers: "".to_string(),
    };
    let resp2 = route_request(req2.path);
    println!("Request: GET /metrics");
    println!("Response: {} - {}", resp2.status, resp2.body);

    // 테스트 요청 3: /notfound
    let req3 = HttpRequest {
        method: "GET".to_string(),
        path: "/notfound".to_string(),
        headers: "".to_string(),
    };
    let resp3 = route_request(req3.path);
    println!("Request: GET /notfound");
    println!("Response: {} - {}", resp3.status, resp3.body);

    true
}

fn main() {
    println!("=== FV-Lang HTTP Server Test ===");
    let success = run_http_server();
    if success {
        println!("✅ All tests passed!");
    } else {
        println!("❌ Test failed!");
    }
}

// 테스트 케이스들
#[test]
fn test_parse_request() {
    let req = HttpRequest {
        method: "GET".to_string(),
        path: "/health".to_string(),
        headers: "Host: localhost".to_string(),
    };
    assert!(req.method == "GET".to_string());
    assert!(req.path == "/health".to_string());
}

#[test]
fn test_health_response() {
    let resp = handle_health();
    assert!(resp.status == 200i32);
    assert!(resp.body.len() > 0i32);
}

#[test]
fn test_metrics_response() {
    let resp = handle_metrics();
    assert!(resp.status == 200i32);
    assert!(resp.body.len() > 0i32);
}

#[test]
fn test_404_response() {
    let resp = route_request("/notfound".to_string());
    assert!(resp.status == 404i32);
}

#[test]
fn test_routing() {
    let resp1 = route_request("/health".to_string());
    let resp2 = route_request("/metrics".to_string());
    assert!(resp1.status == 200i32);
    assert!(resp2.status == 200i32);
}
