    result.count = 0;

    int i = 0;
    int len = strlen(source);

    while (i < len) {
        if (source[i] == 'f' && i + 1 < len && source[i+1] == 'n') {
            strcpy(result.tokens[result.count].type, "KEYWORD");
            strcpy(result.tokens[result.count].value, "fn");
            result.tokens[result.count].line = 1;
            result.tokens[result.count].col = i;
            result.count++;
